CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS football;
CREATE TABLE IF NOT EXISTS football.leagues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS football.clubs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES football.leagues(id),name text NOT NULL,division text,home_ground text,ground_address text,UNIQUE(league_id,name));
CREATE TABLE IF NOT EXISTS football.players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES football.clubs(id),name text NOT NULL,squad_number integer CHECK(squad_number BETWEEN 1 AND 99),registered boolean NOT NULL DEFAULT false,suspended boolean NOT NULL DEFAULT false,registration_source text NOT NULL DEFAULT 'manual_unverified',UNIQUE(club_id,squad_number));
CREATE TABLE IF NOT EXISTS football.fixtures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES football.leagues(id),home_club_id uuid NOT NULL REFERENCES football.clubs(id),away_club_id uuid NOT NULL REFERENCES football.clubs(id),kickoff timestamptz NOT NULL,ground text,max_named_subs integer NOT NULL DEFAULT 7 CHECK(max_named_subs BETWEEN 0 AND 9),max_used_subs integer NOT NULL DEFAULT 5, CHECK(home_club_id<>away_club_id));
CREATE TABLE IF NOT EXISTS football.club_auth_accounts(club_id uuid PRIMARY KEY REFERENCES football.clubs(id),email text NOT NULL UNIQUE,password_salt text NOT NULL,password_hash text NOT NULL,disabled_at timestamptz,last_login_at timestamptz);
CREATE TABLE IF NOT EXISTS football.club_auth_sessions(token_hash text PRIMARY KEY,club_id uuid NOT NULL REFERENCES football.clubs(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS football.team_sheets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fixture_id uuid NOT NULL REFERENCES football.fixtures(id),club_id uuid NOT NULL REFERENCES football.clubs(id),submitted_by text NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fixture_id,club_id));
CREATE TABLE IF NOT EXISTS football.team_sheet_players(sheet_id uuid NOT NULL REFERENCES football.team_sheets(id) ON DELETE CASCADE,player_id uuid NOT NULL REFERENCES football.players(id),selection text NOT NULL CHECK(selection IN ('starter','substitute')),shirt_number integer CHECK(shirt_number BETWEEN 1 AND 99),played boolean NOT NULL DEFAULT false,PRIMARY KEY(sheet_id,player_id));
CREATE TABLE IF NOT EXISTS football.referee_appointments(fixture_id uuid PRIMARY KEY REFERENCES football.fixtures(id),referee_name text,status text NOT NULL DEFAULT 'pending',response_token_hash text UNIQUE,response_token_expires_at timestamptz,updated_at timestamptz);
CREATE TABLE IF NOT EXISTS football.referee_ratings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fixture_id uuid NOT NULL REFERENCES football.fixtures(id),club_id uuid NOT NULL REFERENCES football.clubs(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 10),comments text NOT NULL DEFAULT '',submitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fixture_id,club_id));
INSERT INTO football.leagues(name) VALUES('Chesterfield and District Sunday Football League 2026/27') ON CONFLICT(name) DO NOTHING;
